/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: trackId, assertGoldenOrder, seededRandom, assertDiscOrder, frozenTrack, frozenSingleDiscOrder
 * Tests
 *   - embedded Track Numbers define one order independent of administrator input order
 *   - golden order: missing Track Numbers follow numbered tracks in canonical ID order
 *   - golden order: invalid Track Numbers order exactly like missing ones
 *   - golden order: duplicate Track Numbers and repeated request IDs collapse deterministically
 *   - golden order: ties break by canonical MediaTrack ID with digits before letters
 *   - golden order: a realistic 12-track Album with a gap, a duplicate and untagged tracks
 *   - without valid Disc Numbers the disc-aware order equals the single-disc golden rule
 *   - a 20+19 two-disc Album orders disc 1 then disc 2, each by Track Number
 *   - a missing Disc Number orders as disc 1 and ties with disc 1 by canonical ID
 *   - a track without a Track Number sorts last within its own disc, not last in the Album
 *   - duplicate request IDs collapse in the disc-aware order
 * @end-catalog */

import assert from 'node:assert/strict';
import test from 'node:test';

import {
    sortTrackIdsByDiscAndTrackNumber,
    sortTrackIdsByEmbeddedTrackNumber,
    type AlbumTrackPosition
} from '../../src/services/catalog/albumTrackLinkService';

test('embedded Track Numbers define one order independent of administrator input order', () => {
    const numbers = new Map<string, unknown>([
        ['existing-3', 3],
        ['existing-1', 1],
        ['new-1', 1],
        ['new-2-a', 2],
        ['new-2-b', 2],
        ['invalid', 0]
    ]);

    assert.deepEqual(
        sortTrackIdsByEmbeddedTrackNumber(
            ['existing-3', 'invalid', 'new-2-b', 'new-1', 'new-2-a', 'existing-1'],
            numbers
        ),
        ['existing-1', 'new-1', 'new-2-a', 'new-2-b', 'existing-3', 'invalid']
    );
    assert.deepEqual(
        sortTrackIdsByEmbeddedTrackNumber(
            ['new-1', 'existing-1', 'new-2-a', 'new-2-b', 'existing-3', 'invalid'],
            numbers
        ),
        ['existing-1', 'new-1', 'new-2-a', 'new-2-b', 'existing-3', 'invalid']
    );
});

/*
 * Golden single-disc Album orders, frozen from the pre-Disc-Number code.
 * Persisted Album.audioTrackIds order feeds Album revision hashes, listener
 * DTOs and playback order, so a refactor must not reorder an existing Album.
 * Disc Number ordering (a missing Disc Number orders as disc 1) may adapt how
 * these calls pass metadata, but every expected order below carries no Disc
 * Number and must stay identical. Expected values were captured by running the
 * current code, not derived by hand.
 */

/** Builds a canonical lowercase 24-hex MediaTrack ID that varies only in its last three digits. */
const trackId = (suffix: string) => `665f1c2a9b3e4d0012a4c${suffix}`;

/** Asserts the golden order for the given request order and two fixed permutations of it. */
const assertGoldenOrder = (
    requestOrder: readonly string[],
    trackNumbers: ReadonlyMap<string, unknown>,
    expected: readonly string[]
) => {
    const rotated = [...requestOrder.slice(3), ...requestOrder.slice(0, 3)];
    for (const order of [requestOrder, [...requestOrder].reverse(), rotated]) {
        assert.deepEqual(sortTrackIdsByEmbeddedTrackNumber(order, trackNumbers), expected);
    }
};

test('golden order: missing Track Numbers follow numbered tracks in canonical ID order', () => {
    // 0b2 has an explicit undefined; 0a7 and 009 have no map entry at all.
    assertGoldenOrder(
        [trackId('0c3'), trackId('0a7'), trackId('0f1'), trackId('0b2'), trackId('009'), trackId('0e4')],
        new Map<string, unknown>([
            [trackId('0c3'), 2],
            [trackId('0f1'), 1],
            [trackId('0b2'), undefined],
            [trackId('0e4'), 3]
        ]),
        [trackId('0f1'), trackId('0c3'), trackId('0e4'), trackId('009'), trackId('0a7'), trackId('0b2')]
    );
    assertGoldenOrder(
        [trackId('1d0'), trackId('1a0'), trackId('1f0'), trackId('190')],
        new Map(),
        [trackId('190'), trackId('1a0'), trackId('1d0'), trackId('1f0')]
    );
});

test('golden order: invalid Track Numbers order exactly like missing ones', () => {
    // Only safe integers in 1..9999 are valid; 9999 is the inclusive upper bound.
    const numbers = new Map<string, unknown>([
        [trackId('201'), 0],
        [trackId('202'), -1],
        [trackId('203'), 1.5],
        [trackId('204'), null],
        [trackId('205'), Number.NaN],
        [trackId('206'), Number.POSITIVE_INFINITY],
        [trackId('207'), '2'],
        [trackId('208'), 10_000],
        [trackId('209'), 2 ** 53],
        [trackId('20a'), 9_999],
        [trackId('20b'), 1],
        [trackId('20c'), true]
    ]);
    assertGoldenOrder(
        [...numbers.keys()].reverse(),
        numbers,
        [
            trackId('20b'), trackId('20a'), trackId('201'), trackId('202'),
            trackId('203'), trackId('204'), trackId('205'), trackId('206'),
            trackId('207'), trackId('208'), trackId('209'), trackId('20c')
        ]
    );
});

test('golden order: duplicate Track Numbers and repeated request IDs collapse deterministically', () => {
    assertGoldenOrder(
        [
            trackId('3f0'), trackId('3a0'), trackId('3f0'), trackId('350'),
            trackId('3e0'), trackId('310'), trackId('3c0'), trackId('350')
        ],
        new Map<string, unknown>([
            [trackId('3f0'), 4],
            [trackId('3a0'), 4],
            [trackId('350'), 4],
            [trackId('3e0'), 1],
            [trackId('310'), 1],
            [trackId('3c0'), 2]
        ]),
        [trackId('310'), trackId('3e0'), trackId('3c0'), trackId('350'), trackId('3a0'), trackId('3f0')]
    );
});

test('golden order: ties break by canonical MediaTrack ID with digits before letters', () => {
    // IDs differ at the first character and at each of the last three to pin the comparison.
    const ids = [
        '665f1c2a9b3e4d0012a4c0a1',
        '665f1c2a9b3e4d0012a4c091',
        '665f1c2a9b3e4d0012a4c1ff',
        '565f1c2a9b3e4d0012a4c0ff',
        'a65f1c2a9b3e4d0012a4c000',
        '665f1c2a9b3e4d0012a4c0aa'
    ];
    const expected = [
        '565f1c2a9b3e4d0012a4c0ff',
        '665f1c2a9b3e4d0012a4c091',
        '665f1c2a9b3e4d0012a4c0a1',
        '665f1c2a9b3e4d0012a4c0aa',
        '665f1c2a9b3e4d0012a4c1ff',
        'a65f1c2a9b3e4d0012a4c000'
    ];
    assertGoldenOrder(ids, new Map(ids.map((id) => [id, 7])), expected);
    assertGoldenOrder(ids, new Map(), expected);
});

test('golden order: a realistic 12-track Album with a gap, a duplicate and untagged tracks', () => {
    // Upload IDs are uncorrelated with Track Numbers; there is no track 9 or 10,
    // 9a8 and f13 both claim track 5, 0a2 is tagged 0 and 64f has no tag.
    assertGoldenOrder(
        [
            trackId('b05'), trackId('64f'), trackId('2ee'), trackId('0a2'),
            trackId('f13'), trackId('7e2'), trackId('d71'), trackId('05d'),
            trackId('9a8'), trackId('1b9'), trackId('3c6'), trackId('c40')
        ],
        new Map<string, unknown>([
            [trackId('7e2'), 1],
            [trackId('1b9'), 2],
            [trackId('c40'), 3],
            [trackId('05d'), 4],
            [trackId('f13'), 5],
            [trackId('9a8'), 5],
            [trackId('3c6'), 6],
            [trackId('d71'), 7],
            [trackId('2ee'), 8],
            [trackId('b05'), 11],
            [trackId('0a2'), 0]
        ]),
        [
            trackId('7e2'), trackId('1b9'), trackId('c40'), trackId('05d'),
            trackId('9a8'), trackId('f13'), trackId('3c6'), trackId('d71'),
            trackId('2ee'), trackId('b05'), trackId('0a2'), trackId('64f')
        ]
    );
});

/*
 * Disc Number ordering. These tests only add coverage; the frozen golden
 * calls above keep using the single-disc view unchanged.
 */

/** mulberry32: a tiny seeded PRNG so the property cases are identical on every run. */
const seededRandom = (seed: number) => () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let value = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    value = (value + Math.imul(value ^ (value >>> 7), 61 | value)) ^ value;
    return ((value ^ (value >>> 14)) >>> 0) / 4_294_967_296;
};

/** Asserts a disc-aware order for the request order and the same two fixed permutations as the goldens. */
const assertDiscOrder = (
    requestOrder: readonly string[],
    positions: ReadonlyMap<string, AlbumTrackPosition | undefined>,
    expected: readonly string[]
) => {
    const rotated = [...requestOrder.slice(3), ...requestOrder.slice(0, 3)];
    for (const order of [requestOrder, [...requestOrder].reverse(), rotated]) {
        assert.deepEqual(sortTrackIdsByDiscAndTrackNumber(order, positions), expected);
    }
};

/** Pre-Disc-Number Track Number bounds, frozen so the property oracle cannot drift with the code under test. */
const frozenTrack = (value: unknown) =>
    typeof value === 'number' && Number.isSafeInteger(value) && value > 0 && value <= 9_999 ? value : undefined;

/** Pre-Disc-Number single-disc comparator, frozen as the golden oracle: missing numbers last, then canonical ID. */
const frozenSingleDiscOrder = (ids: readonly string[], numbers: ReadonlyMap<string, unknown>) =>
    [...new Set(ids)].sort((leftId, rightId) => {
        const left = frozenTrack(numbers.get(leftId));
        const right = frozenTrack(numbers.get(rightId));
        if (left === undefined && right === undefined) return leftId.localeCompare(rightId);
        if (left === undefined) return 1;
        if (right === undefined) return -1;
        return left - right || leftId.localeCompare(rightId);
    });

test('without valid Disc Numbers the disc-aware order equals the single-disc golden rule', () => {
    const random = seededRandom(0x5eed2a);
    const trackValues: unknown[] = [0, -1, 1.5, 10_000, '2', null, undefined];
    const invalidDiscs: unknown[] = [0, 1_000, '2', null, 1.5, true];
    for (let caseIndex = 0; caseIndex < 300; caseIndex += 1) {
        const count = 1 + Math.floor(random() * 40);
        const ids = [...new Set(Array.from({ length: count }, () =>
            trackId(Math.floor(random() * 4_096).toString(16).padStart(3, '0'))))];
        const trackNumbers = new Map<string, unknown>();
        for (const id of ids) {
            const pick = random();
            if (pick < 0.15) continue; // no map entry at all
            trackNumbers.set(id, pick < 0.35
                ? trackValues[Math.floor(random() * trackValues.length)]
                : 1 + Math.floor(random() * 9_999));
        }
        const request = [...ids];
        for (let index = request.length - 1; index > 0; index -= 1) {
            const swap = Math.floor(random() * (index + 1));
            [request[index], request[swap]] = [request[swap], request[index]];
        }
        const expected = frozenSingleDiscOrder(request, trackNumbers);
        assert.deepEqual(sortTrackIdsByEmbeddedTrackNumber(request, trackNumbers), expected, `case ${caseIndex}`);
        const withoutDisc = new Map([...trackNumbers].map(([id, trackNumber]) => [id, { trackNumber }]));
        const discOne = new Map(ids.map((id) => [id, { discNumber: 1, trackNumber: trackNumbers.get(id) }]));
        const invalidDisc = new Map(ids.map((id, index) => [id, {
            discNumber: invalidDiscs[index % invalidDiscs.length],
            trackNumber: trackNumbers.get(id)
        }]));
        assert.deepEqual(sortTrackIdsByDiscAndTrackNumber(request, withoutDisc), expected, `case ${caseIndex}`);
        assert.deepEqual(sortTrackIdsByDiscAndTrackNumber(request, discOne), expected, `case ${caseIndex}`);
        assert.deepEqual(sortTrackIdsByDiscAndTrackNumber(request, invalidDisc), expected, `case ${caseIndex}`);
    }
});

test('a 20+19 two-disc Album orders disc 1 then disc 2, each by Track Number', () => {
    const random = seededRandom(0xd15c);
    const ids = [...new Set(Array.from({ length: 80 }, () =>
        trackId(Math.floor(random() * 4_096).toString(16).padStart(3, '0'))))].slice(0, 39);
    assert.equal(ids.length, 39);
    // IDs are uncorrelated with positions: disc 2 tracks take the first 19 random IDs.
    const discTwo = ids.slice(0, 19);
    const discOne = ids.slice(19);
    const positions = new Map<string, AlbumTrackPosition>([
        ...discOne.map((id, index): [string, AlbumTrackPosition] => [id, { discNumber: 1, trackNumber: 20 - index }]),
        ...discTwo.map((id, index): [string, AlbumTrackPosition] => [id, { discNumber: 2, trackNumber: 19 - index }])
    ]);
    const expected = [...[...discOne].reverse(), ...[...discTwo].reverse()];
    assertDiscOrder(ids, positions, expected);
    assertDiscOrder([...ids].sort(), positions, expected);
});

test('a missing Disc Number orders as disc 1 and ties with disc 1 by canonical ID', () => {
    const positions = new Map<string, AlbumTrackPosition>([
        [trackId('a03'), { discNumber: 1, trackNumber: 3 }],
        [trackId('503'), { trackNumber: 3 }],
        [trackId('f01'), { discNumber: 1, trackNumber: 1 }],
        [trackId('104'), { discNumber: 2, trackNumber: 1 }],
        [trackId('702'), { discNumber: null, trackNumber: 2 }]
    ]);
    assertDiscOrder(
        [trackId('104'), trackId('a03'), trackId('702'), trackId('503'), trackId('f01')],
        positions,
        [trackId('f01'), trackId('702'), trackId('503'), trackId('a03'), trackId('104')]
    );
});

test('a track without a Track Number sorts last within its own disc, not last in the Album', () => {
    const positions = new Map<string, AlbumTrackPosition>([
        [trackId('001'), { discNumber: 3, trackNumber: 1 }],
        [trackId('002'), { discNumber: 2 }],
        [trackId('003'), { discNumber: 2, trackNumber: 2 }],
        [trackId('004'), { discNumber: 2, trackNumber: 1 }],
        [trackId('005'), { trackNumber: 1 }],
        [trackId('006'), { discNumber: 2, trackNumber: 0 }]
    ]);
    assertDiscOrder(
        [trackId('001'), trackId('002'), trackId('003'), trackId('004'), trackId('005'), trackId('006')],
        positions,
        [trackId('005'), trackId('004'), trackId('003'), trackId('002'), trackId('006'), trackId('001')]
    );
});

test('duplicate request IDs collapse in the disc-aware order', () => {
    const positions = new Map<string, AlbumTrackPosition>([
        [trackId('0b0'), { discNumber: 2, trackNumber: 1 }],
        [trackId('0a0'), { discNumber: 1, trackNumber: 1 }]
    ]);
    assertDiscOrder(
        [trackId('0b0'), trackId('0a0'), trackId('0b0'), trackId('0a0')],
        positions,
        [trackId('0a0'), trackId('0b0')]
    );
});
